local RegressionTaskContentNode = Class('RegressionTaskContentNode')

function RegressionTaskContentNode:__init()
end

function RegressionTaskContentNode:__delete()
end

function RegressionTaskContentNode:Awake()
    SetButtonAction(self.BtnGo, function()
        if self:GetBtnCB() then
            self:GetBtnCB()(self:GetCellDt(), self:GetStatus(), checkInt(self:GetCellDt().openType), checkInt(self.index_))
        end
    end)
end

function RegressionTaskContentNode:Start()
end

function RegressionTaskContentNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

---@return {taskId : integer, taskTitle : string, desc : string, targetNum : integer, reward : table, openType : integer, status : integer, progress : integer, unlockDayNum : integer, point : integer}
function RegressionTaskContentNode:GetCellDt()
    return checkTable(self.cellDt_)
end

function RegressionTaskContentNode:GetStatus()
    return checkInt(self:GetCellDt().status)
end

function RegressionTaskContentNode:SetBtnCB(handler)
    self.btnCb_ = handler
end
function RegressionTaskContentNode:GetBtnCB()
    return self.btnCb_
end

function RegressionTaskContentNode:RefreshSelf(data, index)
    self.cellDt_ = checkTable(data)
    self.index_  = checkInt(index)

    CfUtils.FillText(self.TxtNumber, self:GetCellDt().point)
    CfUtils.FillText(self.NameTxt, self:GetCellDt().name)

    local progress = math.min(checkNumber(self:GetCellDt().progress), checkNumber(self:GetCellDt().targetNum))
    CfUtils.FillText(self.TitleTxt, string.format("%s/%s", progress, self:GetCellDt().targetNum))

    self.Slider.value = self:GetCellDt().progress / self:GetCellDt().targetNum

    if isNull(self.CommonGoodsList.Env) then
        self.CommonGoodsList:Init()
    end
    self.CommonGoodsList.Env:FreshBaseUI(self:GetCellDt().rewards, false)
    self:UpdateStatus()
end

function RegressionTaskContentNode:UpdateStatus()
    local isCan = self:GetStatus() == Constants.GetStatus.Can
    local isGot = self:GetStatus() == Constants.GetStatus.Has
    local isNot = self:GetStatus() == Constants.GetStatus.Not
    local isCanJump = isNot and checkInt(self:GetCellDt().openType) > 0
    KTool.SetActive(self.HasDrawnNode, isGot)
    KTool.SetActive(self.ProgressNode, isNot and checkInt(self:GetCellDt().openType) <= 0)

    KTool.SetActive(self.BtnGo, isCan or isCanJump)
    if isCan then
        self.BtnGo:ResetFontStyle("B23", localize("领取"))
    elseif isCanJump then
        self.BtnGo:ResetFontStyle("B24", localize("前往"))
    end

    CfUtils.PlayAnimation(self.Container, isCan and "OverseaTasksDialogCellCompleteGo" or "OverseaTasksDialogCellGo")
end

function RegressionTaskContentNode:PlayCompleteAnim()
    CfUtils.PlayAnimation(self.Container.transform:Find("Root"), "OverseaTasksDialogCellCompleteGo_Active")
end


return RegressionTaskContentNode
 
 